#!/usr/bin/env node
/**
 * Builds constants/activityIcons.ts from the design's icon set (crewup-icons.js), plus the overrides below.
 *
 *   npm run icons:activities -- [path/to/crewup-icons.js]
 *
 * The design file defines window.CREWUP_ICONS; it runs here in an isolated VM with only stub globals.
 * Icons are 48×48 monoline: the app draws them with fill none, stroke currentColor, width 2.2, round caps and joins.
 * Re-run after the design adds or changes icons, and commit the generated file.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import vm from 'node:vm';

const appRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source =
  process.argv[2] ??
  path.resolve(appRoot, '../documentation/designs/Flight crew activity app branding/crewup-icons.js');
const target = path.resolve(appRoot, 'constants/activityIcons.ts');

const window = {};
const sandbox = {
  window,
  HTMLElement: class {},
  customElements: { get: () => true, define: () => undefined },
  document: { createElement: () => ({}) },
};
vm.runInNewContext(readFileSync(source, 'utf8'), sandbox, { filename: path.basename(source), timeout: 2000 });
const flat = window.CREWUP_ICONS?.FLAT;
if (!flat) throw new Error(`No CREWUP_ICONS.FLAT in ${source}`);

const p = (d) => `<path d="${d}"/>`;
const c = (x, y, r) => `<circle cx="${x}" cy="${y}" r="${r}"/>`;
const dot = (x, y, r) => `<circle cx="${x}" cy="${y}" r="${r}" fill="currentColor" stroke="none"/>`;
const e = (x, y, rx, ry) => `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}"/>`;
const g = (transform, inner) => `<g transform="${transform}">${inner}</g>`;

/** New or redrawn for the Drinks and Events groups (activities restructure, Nov 2026). */
const OVERRIDES = {
  cocktail: p('M7 10h34L24 27z M24 27v13 M16 41h16 M12 14.5h24 M32.5 5.5l7 7') + c(36, 9, 5),
  wine: p(
    'M10 6h16c0 10-3.5 16-8 16s-8-6-8-16z M18 22v17 M11 41h14 M10.5 12h15 M34 5h6 M35 5v8c-2.5 1.5-3.5 3.5-3.5 6.5V40a2 2 0 002 2h5a2 2 0 002-2V19.5c0-3-1-5-3.5-6.5V5 M31.5 26h11',
  ),
  detox_juice:
    p('M13 16h22l-3 26H16z M14 24h20 M27 16l5-12h6 M10 13c-4-1-6-4-5-8 4 1 6 4 5 8z') + dot(20, 32, 1.6) + dot(26, 35, 1.6) + dot(25, 29, 1.6),
  sporting_events: p(
    'M4 26c0-5 9-9 20-9s20 4 20 9v10c0 5-9 9-20 9S4 41 4 36z M4 26c0 5 9 9 20 9s20-4 20-9 M12 23.5c2-2 7-3 12-3s10 1 12 3 M24 17V4 M24 4l8 3-8 3',
  ),
  music_event: p('M4 42h40 M8 42V22h32v20 M6 22l4-6h28l4 6 M15 16L9 4 M33 16l6-12 M22 37V28l8-2v9') + c(20, 37, 2) + c(28, 35, 2),
  // Onboarding set of 24 (Nov 2026): Fishing is new; Football is now American football.
  fishing: p('M6 40L34 8 M34 8v20 M34 28c0 3.5-4 3.5-4 .5 M24 40c3-4 9-4 12 0-3 4-9 4-12 0z M36 40l5-3.5v7z') + c(12, 33, 3),
  football: g(
    'rotate(-40 24 24)',
    e(24, 24, 19, 11) +
      p('M16 24h16 M18 21v6 M22 21v6 M26 21v6 M30 21v6 M10 17c2.5 3.5 2.5 10.5 0 14 M38 17c-2.5 3.5-2.5 10.5 0 14'),
  ),
};

/** Soccer takes the design's round ball, which was drawn for "football" before it meant American football. */
if (!flat.football) throw new Error('The design set has no football (soccer ball) icon to move to soccer.');
OVERRIDES.soccer = flat.football.svg;

const icons = Object.fromEntries(Object.entries(flat).map(([slug, item]) => [slug, item.svg]));
Object.assign(icons, OVERRIDES);

/**
 * Stored slugs that draw another icon. The catalogue keeps its original slugs (cocktail_bar, wine_tasting,
 * craft_beer, music_festival) so saved picks are untouched; they show the new drawings. Beer and coffee reuse
 * the existing mug and cup.
 */
const ALIASES = {
  cocktail_bar: 'cocktail',
  wine_tasting: 'wine',
  beer: 'craft_beer',
  music_festival: 'music_event',
};
for (const [slug, to] of Object.entries(ALIASES)) icons[slug] = icons[to];

const entries = Object.keys(icons)
  .sort()
  .map((slug) => `  ${/^[a-z_][a-z0-9_]*$/.test(slug) ? slug : JSON.stringify(slug)}: ${JSON.stringify(icons[slug])},`);

writeFileSync(
  target,
  `/* Generated by scripts/generate-activity-icons.mjs from the design's crewup-icons.js. Do not edit by hand. */

/** Inner SVG markup per activity slug, on a 48×48 viewBox. Drawn monoline with stroke="currentColor". */
export const ACTIVITY_ICONS: Record<string, string> = {
${entries.join('\n')}
};
`,
);
console.log(`Wrote ${Object.keys(icons).length} icons to ${path.relative(appRoot, target)}.`);
